function renderGlossary(){
  const box=$('glossaryTable'); if(!box)return;
  const q=norm($('glossarySearch')?.value||''); const f=$('glossaryFilter')?.value||'all';
  const rows=ABBREVIATIONS.filter(x=>{const hay=norm([x.t,x.d,x.w].join(' '));return (!q||hay.includes(q))&&(f==='all'||x.c===f);}).sort((a,b)=>a.t.localeCompare(b.t,'tr'));
  box.innerHTML='<div class="glossary-row head"><div>Kısaltma</div><div>Türkçe / açıklama</div><div>Kullanıldığı yer</div></div>'+rows.map(x=>`<div class="glossary-row"><div class="term">${x.t}</div><div class="desc">${x.d}</div><div class="where">${x.w}</div></div>`).join('')||'<div class="empty">Eşleşen kısaltma bulunamadı.</div>';
}

function isAdminMode(){ return false; }
// Public build: admin mode intentionally disabled.
window.DRUGSAFE_ADMIN_KEY='';
function switchTab(name){
  const adminTabs=['validation','database','sources'];
  if(adminTabs.includes(name)){
    showToast('Bu bölüm yalnızca yönetici panelinden erişilebilir.');
    name='analysis';
  }

  document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));
  $('tab-'+name).classList.add('active');
  document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.tab===name));
  if(name==='renal'){renderRenalCenterV12();renderV13Scenario();renderV13ThresholdTable();}
  if(name==='database')renderDb();
  if(name==='sources')renderSources();
  if(name==='glossary')renderGlossary();
}
function showToast(msg){
  const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),1800);
}
function renderDoseLibrary(){
  const box=$('doseTable'); if(!box)return;
  const q=norm($('doseSearch')?.value||''); const f=$('doseFilter')?.value||'all';
  const all=[...DB.drugs,...COMMON_DOSE_LIBRARY];
  const filtered=all.filter(d=>{
    const txt=norm([d.name,d.displayName,d.class,d.icuUse,d.standardDose,d.renalRuleText,d.criticalNote].join(' '));
    const match=!q||txt.includes(q);
    const isU=!!(ADULT_UCSF_DOSES[d.name]||ADULT_UCSF_DOSES[d.displayName]);
    const isR=!!d.renalRuleText||!!d.renalInfo||!!d.structuredRenal;
    const pass=f==='all'||(f==='ucsf'&&isU)||(f==='icu200'&&!!d.workbookRow)||(f==='renal'&&isR);
    return match&&pass;
  });
  if(!filtered.length){box.innerHTML='<div class="empty">Eşleşen erişkin doz kaydı bulunamadı.</div>';return;}
  box.innerHTML='<div class="dose-row head"><div>İlaç</div><div>Standart erişkin doz</div><div>Renal / diyaliz</div><div>Kaynak</div></div>'+filtered.map(d=>{
    const isU=!!(ADULT_UCSF_DOSES[d.name]||ADULT_UCSF_DOSES[d.displayName]);
    const src=isU?(ADULT_UCSF_DOSES[d.name]||ADULT_UCSF_DOSES[d.displayName]).source:(d.sourceUrl||'');
    return `<details class="dose-detail-row"><summary><div class="dose-row">`+
      `<div><div class="primary">${displayName(d.name)}</div><div class="muted">${d.class||''}</div></div>`+
      `<div class="muted">${d.standardDose||'Veri yok'}</div>`+
      `<div class="muted">${d.renalRuleText||d.renalInfo||'Ayrı renal doz metni yok'}</div>`+
      `<div>${src?`<a href="${src}" target="_blank" rel="noopener" style="color:#356bb0;text-decoration:none">Aç</a>`:''}</div>`+
      `</div></summary><div style="padding:10px 12px 12px">${renderAdultDoseTableDetail(d)}</div></details>`;
  }).join('');
}

function reset(){
  selected.splice(0,selected.length);renderSelected();
  ['age','weight','height','cr','egfr','ast','alt','bili','albumin','inr','hdHours','crrtEffluent','crrtDowntime','crrtPredilution','pdExchanges','pdFill','cr24','cr48','crBaseline7','urineVol'].forEach(id=>$(id) && ($(id).value=''));
  $('sex').value='male';$('ascites').value='none';$('enceph').value='none';$('dialysis').value='none';$('context').value='icu_severe';$('renalStability').value='stable'; if($('rrtIndication'))$('rrtIndication').value='chronic'; if($('hdToday'))$('hdToday').value='yes'; if($('hdFrequency'))$('hdFrequency').value='3x'; if($('hdLast'))$('hdLast').value='today'; if($('crrtMode'))$('crrtMode').value='CVVHDF'; if($('crrtDowntime'))$('crrtDowntime').value='0'; if($('crrtPredilution'))$('crrtPredilution').value='0'; if($('pdMode'))$('pdMode').value='CAPD'; if($('pdLast'))$('pdLast').value='today'; if($('urineHours'))$('urineHours').value=''; if($('hdToday'))$('hdToday').value='yes'; if($('hdFrequency'))$('hdFrequency').value='3x'; if($('hdLast'))$('hdLast').value='today'; if($('crrtMode'))$('crrtMode').value='CVVHDF'; if($('crrtDowntime'))$('crrtDowntime').value='0'; if($('crrtPredilution'))$('crrtPredilution').value='0'; if($('pdMode'))$('pdMode').value='CAPD'; if($('pdLast'))$('pdLast').value='today'; if($('urineHours'))$('urineHours').value='';
  renderMetrics();$('summary').innerHTML='';$('doseEngine').innerHTML='<div class="empty">Analiz sonrası böbrek doz referansı burada görünecek.</div>';renderV13Insights();renderV13Scenario();renderV13ThresholdTable();$('report').innerHTML='<div class="empty">Henüz analiz yapılmadı.</div>';$('reportStatus').textContent='İlaç ekleyin ve analizi çalıştırın.';
}

