const V20_META = {
  version:'2.0.0',
  buildDate:'2026-09-21',
  scope:'Erişkin • 393 temel + 10 Stanford/common aranabilir ilaç • renal + hepatik + etkileşim + duplicate + izlem + kaynak + güvenlik/validasyon'
};

function drugMatches(name, arr){
  const d=getDrug(name); if(!d)return false;
  const keys=[d.name,d.displayName,...(d.aliases||[])].map(norm);
  return arr.some(x=>keys.includes(norm(x)) || norm(x)===norm(d.name));
}
function selectedAny(arr){return selected.some(n=>drugMatches(n,arr));}
function selectedOf(arr){return selected.filter(n=>drugMatches(n,arr));}

