function interactionRuleMatches(rule){
  const left=selectedOf(rule.a), right=selectedOf(rule.b);
  if(rule.skipSame){
    return selected.filter(n=>selectedOf(rule.a).includes(n)).length>=2;
  }
  return left.length>0 && right.length>0 && left.some(a=>!right.includes(a));
}
function enhancedInteractions(){
  const out=[];
  for(const rule of INTERACTION_RULES_V20){ if(interactionRuleMatches(rule)) out.push({...rule,selectedA:selectedOf(rule.a),selectedB:selectedOf(rule.b)}); }
  // QT cluster: any >=2 members, without requiring amiodarone
  const qt=['Amiodaron','Haloperidol','Droperidol','Ondansetron','Azitromisin','Klaritromisin','Eritromisin','Moksifloksasin','Levofloksasin','Sotalol','Prokainamid'];
  const qts=selectedOf(qt);
  if(qts.length>=2 && !out.some(x=>x.id==='amio-qt')) out.push({id:'qt-cluster',sev:'high',title:'Birden fazla QT uzaması riski taşıyan ilaç',text:`Seçilen ilaçlar: ${qts.map(displayName).join(', ')}. Toplam QT yükü ve elektrolitler değerlendirilmelidir.`,tags:['QT','EKG'],source:'https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5520f11d-968d-4f4f-bf57-d14369c0d746'});
  const nephro=selectedOf(['Vancomycin','Gentamisin','Amikasin','Tobramisin','Lipozomal amfoterisin B','Foskarnet','Cidofovir','Ketorolak','İbuprofen IV/PO']);
  if(nephro.length>=2) out.push({id:'nephro-stack',sev:'high',title:'Birden fazla renal toksisite yükü taşıyan ilaç',text:`Seçilen renal-riskli ilaçlar: ${nephro.map(displayName).join(', ')}. Serum kreatinin trendi, sıvı durumu ve gereksiz nefrotoksik eşzamanlılık yeniden değerlendirilmelidir.`,tags:['NEFROTOKSİSİTE','KREATİNİN'],source:'https://kdigo.org/wp-content/uploads/2024/03/KDIGO-2024-CKD-Guideline.pdf'});
  return out;
}

const DUPLICATE_RULES_V20=[
  {class:'Antikoagülan',drugs:['Warfarin','Standart heparin (UFH)','Enoksaparin','Fondaparinuks','Apiksaban','Rivaroksaban','Dabigatran','Argatroban','Bivalirudin']},
  {class:'Antiplatelet',drugs:['Klopidogrel','Ticagrelor']},
  {class:'NSAİİ',drugs:['Ketorolak','İbuprofen IV/PO']},
  {class:'ACE inhibitörü',drugs:['Enalaprilat','Lisinopril']},
  {class:'ARB',drugs:['Losartan','Valsartan']},
  {class:'Beta bloker',drugs:['Metoprolol','Esmolol','Labetalol','Karvedilol']},
  {class:'Loop diüretik',drugs:['Furosemid','Bumetanid']},
  {class:'Opioid analjezik',drugs:['Fentanil','Morfin','Hidromorfon','Oksikodon','Remifentanil','Tramadol']}
];
function duplicateFindings(){
  const out=[];
  for(const g of DUPLICATE_RULES_V20){const hits=selectedOf(g.drugs);if(hits.length>=2)out.push({class:g.class,drugs:hits,title:`${g.class}: birden fazla ilaç`,text:`${hits.map(displayName).join(' + ')} aynı/benzer terapötik sınıfta. Geçiş veya özel endikasyon yoksa gereksiz eşzamanlılık doğrulanmalıdır.`});}
  if(selectedAny(['Lisinopril','Enalaprilat'])&&selectedAny(['Sakubitril/valsartan']))out.push({class:'ACEİ + ARNI',drugs:selected.filter(n=>drugMatches(n,['Lisinopril','Enalaprilat','Sakubitril/valsartan'])),title:'ACE inhibitörü + ARNI',text:'Birlikte kullanım güvenlik açısından ayrıca doğrulanmalıdır; geçiş protokolünü kontrol edin.'});
  return out;
}

