/* ===== DrugSafe AI v3.2 Renal + Dialysis Expansion ===== */
const RENAL_V32 = DB.renalCoverage || {};

function contextScoreV32(ind, ctx){
  const s=(ind||'').toLocaleLowerCase('tr-TR');
  const kws = {
    cns:['menenjit','cns','sss'],
    febrile_neutropenia:['febril','nötropeni'],
    nosocomial_pneumonia:['hastane','pseudomonas','pnömoni','pneumonia'],
    cSSTI:['cilt','yumuşak doku'],
    bacteremia:['bakteriyemi','bloodstream','kan dolaş'],
    prophylaxis:['profilaksi','prophylaxis'],
    treatment:['tedavi'],
    uncomplicated:['komplike olmayan','sistit'],
    icu_severe:['şiddetli','ağır','ciddi','komplike','yoğun bakım'],
    standard:['standart','tüm endikasyon','diğer']
  };
  const arr=kws[ctx]||[];
  let score=0; for(const k of arr) if(s.includes(k)) score+=2;
  if(ctx==='icu_severe' && /profilaksi|prophylaxis/.test(s)) score-=3;
  return score;
}
function detailedDoseV32(d,c){
  const rows=d.renalModel?.detailRows||[];
  if(!rows.length || c==null) return null;
  const ctx=contextValue();
  const scored=rows.map((r,i)=>({r,i,score:contextScoreV32(r.indication,ctx)}))
                    .sort((a,b)=>b.score-a.score || a.i-b.i);
  const best=scored[0];
  if(!best) return null;
  const rr=(best.r.rules||[]).filter(x=>Number.isFinite(x.min)&&Number.isFinite(x.max));
  let match=rr.find(x=>c>=x.min&&c<=x.max);
  if(!match){
    // Fallback to a Tüm CrCl row if one exists
    match=rr.find(x=>x.min<=0&&x.max>=9998);
  }
  if(!match) return {kind:'detailed-manual',dose:'Endikasyon / renal kural kontrolü gerekli',note:`Kaynaklı ayrıntılı tabloda “${best.r.indication}” satırı var ancak mevcut CrCl için otomatik eşleşme bulunamadı.`,source:d.renalModel?.sourceUrl||d.sourceUrl};
  return {kind:'detailed',dose:match.dose,note:`Endikasyon: ${best.r.indication}. Koşul: ${match.condition}.`,source:d.renalModel?.sourceUrl||d.sourceUrl};
}
function dialysisDecisionV32(d,mod){
  const r=d.renalModel?.dialysis?.[mod];
  if(!r || r.status==='no_data'){
    return {status:'manual',sourceType:'Diyaliz kaynak kontrolü',dose:'Kaynak kontrolü gerekli',note:`${mod.toUpperCase()} için ilaç-özel yapılandırılmış diyaliz kuralı bulunmuyor. Güncel ürün bilgisi / kurum protokolü kontrol edilmeli.`,source:d.renalModel?.sourceUrl||d.sourceUrl};
  }
  if(r.status==='avoid'){
    return {status:'high',sourceType:'Diyalizde kaçınma notu',dose:'Yüksek öncelikli diyaliz/renal güvenlik',note:r.note||r.dose,source:d.renalModel?.sourceUrl||d.sourceUrl,high:true};  }
  if(r.status==='none'){
    return {status:'none',sourceType:'Diyalize bağlı doz değişikliği yok',dose:'Diyalize bağlı doz değişikliği yok',note:r.note||r.dose,source:d.renalModel?.sourceUrl||d.sourceUrl,high:d.nephrotoxicity==='high'};
  }
  if(r.status==='dose' || r.status==='timing'){
    return {status:'dose',sourceType:'İlaç-özel diyaliz kuralı',dose:r.dose||'Diyalize özel doz',note:r.note||'',source:d.renalModel?.sourceUrl||d.sourceUrl,high:d.nephrotoxicity==='high'};
  }
  return {status:'manual',sourceType:'Diyaliz kaynak kontrolü',dose:'Kaynak kontrolü gerekli',note:r.note||r.dose||'Diyaliz kuralı bireyselleştirilmeli.',source:d.renalModel?.sourceUrl||d.sourceUrl,high:d.nephrotoxicity==='high'};
}

function structuredDoseFromDrug(d,c,dialysis){
  // V3.2: if dialysis is selected, dialysis-specific rules take precedence.
  const dk = dialysisKey();
  if(dk){
    const dr=dialysisDecisionV32(d,dk);
    if(dr.status==='manual') return null;
    return {kind:dr.status==='dose'?'structured-dialysis':'structured-dialysis-none',dose:dr.dose,note:dr.note,source:dr.source};
  }
  const detail=detailedDoseV32(d,c);
  if(detail){
    if(detail.kind==='detailed-manual') return null;
    return {kind:'structured',dose:detail.dose,note:detail.note,source:detail.source};
  }
  const rm=d.renalModel;
  if(rm && (rm.rules||[]).length && c!=null){
    const ctx=contextValue();
    const r=(rm.rules||[]).find(x=>c>=x.min&&c<=x.max);
    if(r) return {kind:'structured',dose:r.dose||'Kural bulundu',note:r.sourceText||r.note||'',source:rm.sourceUrl||d.sourceUrl};
  }
  return null;
}

function renalDecisionV12(d){
  const c=calcCrCl(), rrt=dialysisKey();
  if(rrt){
    return dialysisDecisionV32(d,rrt);
  }
  if(c==null) return {status:'manual',sourceType:'CrCl eksik',dose:'CrCl gerekli',note:'Renal karar için yaş, kilo ve serum kreatinin ile CrCl hesaplanmalı.',source:d.renalModel?.sourceUrl||d.sourceUrl};
  const det=detailedDoseV32(d,c);
  if(det){
    if(det.kind==='detailed-manual') return {status:'manual',sourceType:'Ayrıntılı kaynak • manuel kontrol',dose:det.dose,note:det.note,source:det.source,high:d.nephrotoxicity==='high'};
    return {status:'dose',sourceType:'Kaynaklı ayrıntılı erişkin kural',dose:det.dose,note:det.note,source:det.source,high:d.nephrotoxicity==='high'};
  }
  const rm=d.renalModel||{};
  const band=rm.rules?.find(x=>c>=x.min&&c<=x.max);
  if(band) return {status:'dose',sourceType:rm.externalVerified?'Kaynaklı CrCl kuralı':'CrCl kuralı • çalışma kitabı',dose:band.dose||'İlgili CrCl aralığı bulundu',note:`Eşleşen renal koşul: ${band.condition||''}`,source:rm.sourceUrl||d.sourceUrl,band,high:d.nephrotoxicity==='high'};
  if(rm.mode==='avoid') return {status:'high',sourceType:'Yüksek öncelikli renal güvenlik',dose:'Yüksek öncelikli renal güvenlik değerlendirmesi',note:rm.statusText||d.renalRuleText,source:rm.sourceUrl||d.sourceUrl,high:true};
  if(rm.mode==='no_adjustment') return {status:'none',sourceType:'Rutin renal doz değişikliği yok',dose:'Rutin renal doz ayarı belirtilmemiş',note:rm.statusText||'Rutin renal doz değişikliği belirtilmemiş.',source:rm.sourceUrl||d.sourceUrl,high:false};
  return {status:'manual',sourceType:'Kaynak kontrolü gerekli',dose:'Kaynak kontrolü gerekli',note:rm.statusText||d.renalRuleText||'Renal dozlama için yapılandırılmış spesifik doz bilgisi bulunmuyor.',source:rm.sourceUrl||d.sourceUrl,high:d.nephrotoxicity==='high'};
}

function renalFilterPassV12(d,dec,q,bandFilter){
  const t=norm([d.name,d.displayName,d.class,d.icuUse].join(' ')); if(q&&!t.includes(q))return false;
  const sf=$('renalStatusFilter')?.value||'all';
  if(sf==='dose' && dec.status!=='dose')return false;
  if(sf==='high' && !dec.high && dec.status!=='high')return false;
  if(sf==='none' && dec.status!=='none')return false;
  if(sf==='manual' && dec.status!=='manual')return false;
  if(sf==='dialysis' && !(dec.sourceType||'').toLocaleLowerCase('tr-TR').includes('diyaliz'))return false;
  const c=calcCrCl(); 
  if(bandFilter!=='all'&&c!=null){const key=c<15?'lt15':c<30?'15to29':c<60?'30to59':'60plus';if(key!==bandFilter)return false;}
  return true;
}

function renderRenalCoverageV12(){
  const total=DB.drugs.length, bands=RENAL_V32.explicitCrClRules||0, detailed=RENAL_V32.detailedExternalTables||0, hd=RENAL_V32.hdExplicit||0, cr=RENAL_V32.crrtExplicit||0, pd=RENAL_V32.pdExplicit||0;
  $('renalCoverageCards').innerHTML=[
    [total,'Benzersiz erişkin ilaç','400 kaynak kaydı • 393 benzersiz','green'],
    [detailed,'Ayrıntılı kaynaklı renal tablo',`${detailed} ilaçta endikasyon bazlı tablo`,'green'],
    [bands,'Açık CrCl kuralı',`${bands} ilaçta CrCl eşikleri yapılandırıldı`,'blue'],
    [hd,'HD bilgisi',`${hd} ilaçta HD kuralı / notu`,'purple'],
    [cr,'CRRT bilgisi',`${cr} ilaçta CRRT kuralı / notu`,'purple'],
    [pd,'PD bilgisi',`${pd} ilaçta PD kuralı / notu`,'purple']
  ].map(x=>`<div class="coverage-card"><div class="num">${x[0]}</div><div class="lbl">${x[1]}</div><div class="pct">${x[2]}</div></div>`).join('');
}

function renderDoseEngine(){
  const c=calcCrCl(), dk=$('dialysis').value;
  if(!selected.length){$('doseEngine').innerHTML='<div class="empty">Önce ilaç seçin.</div>';return}
  const cards=selected.map(name=>{
    const d=getDrug(name), a=renalDecisionV12(d);
    if(!a || !d)return '';
    const cls=a.status==='high'?'high':(a.status==='manual'?'warn':(a.status==='none'?'info':'info'));
    const statusText={
      dose:'KAYNAKLI KURAL',
      high:'YÜKSEK ÖNCELİK',
      none:'RENAL DEĞİŞİKLİK YOK',
      manual:'KAYNAK KONTROLÜ GEREKLİ'
    }[a.status]||'RENAL DEĞERLENDİRME';
    const badgeClass=a.status==='high'?'red':a.status==='manual'?'amber':a.status==='none'?'green':'blue';
    const bandText=a.band?.condition ? `<div class="rule-trace"><strong>Eşleşen koşul:</strong> ${a.band.condition}</div>` : '';
    return `<div class="dose-card ${cls}">
      <div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start">
        <div><div class="drug">${displayName(name)}</div><div class="meta">CrCl ${c==null?'—':c.toFixed(1)+' mL/dk'} • ${renalStabilityText()} • ${dk==='none'?'RRT yok':$('dialysis').options[$('dialysis').selectedIndex].text}</div></div>
        <span class="context-pill">${statusText}</span>
      </div>
      <div class="dose">${a.dose}</div>
      <div class="note">${a.note||''}</div>
      ${bandText}
      <div style="display:flex;justify-content:space-between;align-items:center;gap:8px">
        <span class="evidence ${a.status==='dose'?'ok':a.status==='high'?'pending':'pending'}">${a.sourceType}</span>
        <a style="font-size:8px;color:#356bb0;text-decoration:none" target="_blank" rel="noopener" href="${a.source||d.sourceUrl||'#'}">Kaynağı aç</a>
      </div>
    </div>`;
  }).join('');
  $('doseEngine').innerHTML=`<div class="engine-head"><div><strong>Renal motor sonucu</strong><div class="muted">${RENAL_V32.sourceRecords||400} kaynak kaydı • ${RENAL_V32.uniqueDrugs||DB.drugs.length} benzersiz erişkin ilaç • ${RENAL_V32.explicitCrClRules||0} açık CrCl kuralı</div></div><span class="engine-badge">RENAL KURAL KATMANI</span></div>
    <div class="dose-grid">${cards}</div>
    <div class="footer-note">${$('renalStability').value!=='stable'?'ABY/şok işaretli: formül bazlı CrCl/eGFR sonuçları gerçek zamanlı renal klirensi tam temsil etmeyebilir. ':''}Diyaliz seçiliyse ilaç-özel HD/CRRT/PD bilgisi birincil değerlendirmedir. Kaynakta yeterli veri yoksa sistem kesin doz üretmez; güncel ürün bilgisi ve kurum protokolü doğrulanmalıdır.</div>`;
}

function renderRenalCenterV12(){
  renderRenalCoverageV12(); 
  const c=calcCrCl(), q=norm($('renalSearch')?.value||''), bf=$('renalBandFilter')?.value||'all'; 
  const list=DB.drugs.map(d=>({d,dec:renalDecisionV12(d)})).filter(x=>renalFilterPassV12(x.d,x.dec,q,bf)); 
  const rrt=$('dialysis').value==='none'?'RRT yok':$('dialysis').options[$('dialysis').selectedIndex].text;
  $('renalCenterMeta').textContent=`CrCl: ${c==null?'—':c.toFixed(1)+' mL/dk'} • ${bandLabelV12(c)} • ${rrt} • ${list.length}/${DB.drugs.length} ilaç gösteriliyor`;
  if(!list.length){$('renalCenterTable').innerHTML='<div class="empty">Filtreye uyan ilaç bulunamadı.</div>';}
  else{
    const icon=s=>s==='high'?'red':s==='dose'?'amber':s==='none'?'green':'blue'; 
    const label=s=>({high:'Yüksek öncelik',dose:'Doz / interval',none:'Rutin ayar yok',manual:'Kaynak kontrolü'}[s]||'Bilgi');
    const rows=list.map(({d,dec})=>`<div class="renal-row"><div><strong>${displayName(d.name)}</strong><div class="subline">${d.name} • #${d.id}</div></div><div>${d.class||'—'}</div><div><span class="renal-chip ${icon(dec.status)}">${label(dec.status)}</span></div><div>${dec.dose}</div><div><a href="${dec.source||d.sourceUrl||'#'}" target="_blank" rel="noopener" style="font-size:8px;color:#356bb0;text-decoration:none">${dec.sourceType}</a></div></div>`).join('');
    $('renalCenterTable').innerHTML=`<div class="renal-table"><div class="renal-row head"><div>İlaç</div><div>Sınıf</div><div>Durum</div><div>Mevcut renal sonuç</div><div>Kaynak</div></div>${rows}</div>`;
  }
  renderSelectedRenalV12();
}

function renderSelectedRenalV12(){
  const box=$('selectedRenalDetails'); if(!box)return; 
  if(!selected.length){box.innerHTML='<div class="empty">Hasta analizi ekranından ilaç seçin.</div>';return}
  const c=calcCrCl(); 
  box.innerHTML='<div class="selected-renal">'+selected.map(name=>{
    const d=getDrug(name),dec=renalDecisionV12(d),rm=d.renalModel||{},bands=rm.rules||[];
    const dialysis=$('dialysis').value!=='none' ? (()=>{const m=dialysisKey(),r=rm.dialysis?.[m]; return r&&r.status!=='no_data'?`<div class="band-box"><div class="band-title">${m.toUpperCase()} ilaca özel kural</div><div style="font-size:10px;font-weight:900;color:#19385f">${r.status==='none'?'Diyalize bağlı doz değişikliği yok':r.status==='avoid'?'Yüksek öncelikli güvenlik':r.status==='review'?'Kaynak kontrolü gerekli':r.dose}</div><div style="font-size:9px;color:#64748b;margin-top:5px">${r.note||''}</div></div>`:'<div class="band-box"><div class="band-title">Diyaliz</div><div style="font-size:9px;color:#64748b">Bu modalite için ilaç-özel yapılandırılmış bilgi yok; kaynak kontrolü gerekli.</div></div>'})():'';
    return `<div class="renal-focus"><div style="display:flex;justify-content:space-between;gap:8px"><div><strong>${displayName(name)}</strong><div class="subline">CrCl ${c==null?'—':c.toFixed(1)+' mL/dk'} • ${bandLabelV12(c)}</div></div><span class="renal-chip ${dec.status==='high'?'red':dec.status==='none'?'green':dec.status==='manual'?'blue':'amber'}">${dec.sourceType}</span></div><div class="band-box"><div class="band-title">Mevcut renal sonuç</div><div style="font-size:10px;font-weight:900;color:#19385f">${dec.dose}</div><div style="font-size:9px;color:#64748b;margin-top:5px">${dec.note||''}</div>${bands.length?`<div class="band-title" style="margin-top:10px">Yapılandırılmış CrCl koşulları</div>${bands.map(b=>`<div class="band-item"><span class="range">${b.condition||''}</span><span class="txt">${b.dose||''}</span></div>`).join('')}`:''}</div>${dialysis}<div style="margin-top:8px;font-size:8px;color:#7b8798"><strong>Nefrotoksisite:</strong> ${d.nephrotoxicity||'bilgi yok'} • <strong>TDM:</strong> ${d.tdmText||'belirtilmemiş'}</div><div style="margin-top:7px"><a href="${dec.source||d.sourceUrl||'#'}" target="_blank" rel="noopener" style="font-size:8px;color:#356bb0;text-decoration:none">Kaynağı aç</a></div></div>`;
  }).join('')+'</div>';
}

