async function loadServerOverrides(){
  try{
    const res=await fetch('/api/overrides',{cache:'no-store'});
    if(!res.ok) return;
    const overrides=await res.json();
    const byId={};
    DB.drugs.forEach(d=>byId[d.id]=d);
    Object.entries(overrides||{}).forEach(([id,patch])=>{ const d=byId[id]; if(d) Object.assign(d,patch); });
    renderSearch($('drugSearch')?.value||''); renderMetrics(); renderSelected(); renderDoseLibrary(); renderV13Insights(); renderV13Scenario(); renderV13ThresholdTable();
  }catch(e){ console.warn('Sunucu verileri yüklenemedi; yerel veri kullanılıyor.',e); }
}
loadServerOverrides();